<script setup lang="ts">
import zh from '../../../i18n/locales/zh-CN.json'
import en from '../../../i18n/locales/en-US.json'
import ja from '../../../i18n/locales/ja-JP.json'
const props=defineProps<{taskId:string}>()
const {t:uiT,locale:appLocale}=useI18n({useScope:'global'})
const preference=useCookie<string|null>('wms_print_language',{maxAge:31536000,sameSite:'lax'})
const initial=preference.value||appLocale.value
const {t,locale}=useI18n({useScope:'local',inheritLocale:false,locale:initial==='zh'||initial==='ja'?initial:'en',messages:{zh,en,ja}})
watch(locale,value=>preference.value=value)
const record=ref<any>(null),plan=ref<any>(null),loading=ref(true),error=ref(''),staff=useStaffStore(),{bizErrorMessage}=useBizError()
const company=computed(()=>staff.staffInfo?.company as any),number=computed(()=>'PICK-'+props.taskId)
const rows=computed(()=>plan.value?.rows||[])
const locationCount=computed(()=>new Set(rows.value.map((row:any)=>row.location)).size)
const total=computed(()=>rows.value.reduce((sum:number,row:any)=>sum+row.quantity,0))
const print=async()=>{await document.fonts.ready;window.print()}
let generation=0
watch(()=>props.taskId,async()=>{const seq=++generation;record.value=null;plan.value=null;loading.value=true;error.value='';const onError=(e:any)=>{if(seq===generation)error.value=bizErrorMessage(e)};const [task,result]=await Promise.all([httpRequest<any>('/api/warehouse/picking/'+props.taskId,{onError}),httpRequest<any>('/api/warehouse/picking/'+props.taskId+'/print-plan',{onError})]);if(seq===generation){record.value=task;plan.value=result;loading.value=false}},{immediate:true})
onBeforeUnmount(()=>generation++)
useHead({title:()=>number.value+' · '+t('pick-print.title')})
</script>
<template><div class="pick-print w-scope"><div class="toolbar"><NuxtLink :to="'/picking/detail/'+taskId">{{number}}</NuxtLink><label>{{uiT('print-design.language')}}<select v-model="locale"><option value="zh">中文</option><option value="en">English</option><option value="ja">日本語</option></select></label><WButton icon="printer" :disabled="loading||!record||!plan" @click="print">{{uiT('button.print-to-pdf')}}</WButton></div><WAlert v-if="error" tone="block" :title="error"/><WEmptyState v-if="loading" :title="uiT('common.status.loading')"/><div class="paper-scroll"><article v-if="record&&plan" class="paper" :lang="locale==='ja'?'ja':locale==='zh'?'zh-CN':'en'">
<header><div class="company"><strong>{{company?.name}}</strong><span>{{company?.address}}</span><span>{{company?.phone}}<template v-if="company?.email"> · {{company.email}}</template></span></div><div class="title"><h1>PICK LIST</h1><span>{{t('pick-print.title')}}</span><div class="barcode-row"><div><Barcode :value="number" :options="{displayValue:false,margin:0,height:32}"/><b class="number">{{number}}</b></div></div></div></header>
<div class="references"><div><small>PICK NO.</small><b>{{number}}</b></div><div><small>DN NO.</small><b>DN-{{record.dn_id}}</b></div><div><small>{{t('nav.warehouse')}}</small><b>{{record.dn?.warehouse?.name||'—'}}</b></div><div><small>{{t('document-report.planned')}}</small><b>{{record.dn?.expected_shipping_date||'—'}}</b></div></div>
<div class="parties"><div><small>SHIP TO · {{t('nav.recipient')}}</small><b>{{record.dn?.recipient?.name||'—'}}</b><span>{{record.dn?.shipping_address||'—'}}</span></div><div><small>CARRIER · {{t('nav.carrier')}}</small><b>{{record.dn?.carrier?.name||'—'}}</b></div><div class="handling"><small>HANDLING · {{t('pick-print.handling')}}</small><b>{{record.dn?.special_handling||'—'}}</b></div></div>
<div class="summary"><div><small>LOCATIONS · {{t('nav.location')}}</small><b>{{locationCount}}</b></div><div><small>LINES · {{t('count-print.lines')}}</small><b>{{rows.length}}</b></div><div><small>PCS · {{t('pick-print.quantity')}}</small><b>{{total}}</b></div><div><small>{{t('pick-print.mode')}}</small><b>{{t('pick-print.'+plan.mode)}}</b></div></div>
<p class="plan-note">{{t('pick-print.'+(plan.mode==='record'?'record-help':'suggestion-help'))}}</p><h2>PICK LINES · BY LOCATION <span>{{t('pick-print.by-location')}}</span></h2>
<table class="pick-lines"><colgroup><col style="width:34px"/><col style="width:118px"/><col/><col style="width:62px"/><col style="width:72px"/><col style="width:62px"/><col style="width:62px"/><col style="width:26px"/></colgroup><thead><tr><th>#</th><th>LOCATION<span>{{t('nav.location')}}</span></th><th>GOODS<span>{{t('nav.goods')}}</span></th><th>LOT<span>{{t('count-print.lot')}}</span></th><th>EXPIRY<span>{{t('count-print.expiry')}}</span></th><th class="qty">QTY<span>{{t('pick-print.quantity')}}</span></th><th>ACTUAL<span>{{t('common.quantities.actual')}}</span></th><th>✓</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="index"><td class="seq">{{Number(index)+1}}</td><td class="location" :class="{'long-location':String(row.location).length>18}" :style="{fontSize:Math.max(9,Math.min(16,160/String(row.location).length))+'px'}">{{row.location}}</td><td><b>{{row.goods}}</b><span class="code">{{row.code}}</span></td><td>—</td><td>—</td><td class="qty pick-qty">{{row.quantity}}</td><td><i class="write-box"/></td><td><i class="check-box"/></td></tr><tr class="total"><td colspan="5">TOTAL · {{t('pick-print.total')}}</td><td class="qty">{{total}}</td><td><i class="write-box"/></td><td/></tr></tbody></table>
<h2>SHORT PICK / EXCEPTIONS <span>{{t('count-print.exceptions')}}</span></h2><table class="exceptions"><thead><tr><th>{{t('nav.location')}}</th><th>{{t('nav.goods')}}</th><th>{{t('count-print.lot')}}</th><th>{{t('pick-print.quantity')}}</th><th>{{t('common.fields.remark')}}</th></tr></thead><tbody><tr v-for="row in plan.shortages" :key="row.goods_id"><td>—</td><td>{{row.goods}}<span class="code">{{row.code}}</span></td><td>—</td><td>{{row.quantity}}</td><td>{{t('pick-print.shortage')}}</td></tr><tr v-for="n in 3" :key="'blank'+n"><td/><td/><td/><td/><td/></tr></tbody></table>
<div class="closing"><div class="signatures"><section v-for="key in ['picked','checked']" :key="key"><h3>{{t('pick-print.'+key)}}</h3><div><span v-for="field in ['common.fields.name','print-design.signature','print-design.date']" :key="field">{{t(field)}}<i/></span></div></section></div><footer><span>{{company?.name}}</span><span>{{number}} · {{t('pick-print.'+plan.mode)}}</span></footer></div>
</article></div></div></template>
